export type Cell = [x: number, y: number];

const NEIGHBOURS_TO_SURVIVE = [2, 3];
const NEIGHBOURS_TO_BE_BORN = [3];

const NEIGHBOUR_OFFSETS = [-1, 0, 1];

const cellKey = ([x, y]: Cell): string => `${x},${y}`;

const neighboursOf = ([x, y]: Cell): Cell[] =>
  NEIGHBOUR_OFFSETS.flatMap((offsetX) =>
    NEIGHBOUR_OFFSETS.filter(
      (offsetY) => offsetX !== 0 || offsetY !== 0,
    ).map((offsetY): Cell => [x + offsetX, y + offsetY]),
  );

type NeighbourTally = Map<string, { cell: Cell; neighbours: number }>;

const tallyNeighboursOfLiveCells = (liveCells: Cell[]): NeighbourTally => {
  const tally: NeighbourTally = new Map();
  liveCells.flatMap(neighboursOf).forEach((cell) => {
    const key = cellKey(cell);
    const counted = tally.get(key)?.neighbours ?? 0;
    tally.set(key, { cell, neighbours: counted + 1 });
  });
  return tally;
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const liveKeys = new Set(liveCells.map(cellKey));
  return [...tallyNeighboursOfLiveCells(liveCells).values()]
    .filter(({ cell, neighbours }) =>
      (liveKeys.has(cellKey(cell))
        ? NEIGHBOURS_TO_SURVIVE
        : NEIGHBOURS_TO_BE_BORN
      ).includes(neighbours),
    )
    .map(({ cell }) => cell);
}

